/**
 * DashboardPage.js — Role-aware dashboard router
 *
 * Replaces /src/pages/dashboard/DashboardPage.js
 *
 * Routes:
 *   super_admin   → SuperAdminDashboard
 *   chef_projet   → ChefProjetDashboard
 *   all others    → existing role dashboards (from DashboardPage.existing.js)
 */

import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { projectsAPI, teamAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import RoleBadge from '../../components/ui/RoleBadge';
import toast from 'react-hot-toast';

// ── Import the two new specialized dashboards ─────────────────────────────────
// Uncomment these once you've placed the files:
// import SuperAdminDashboard  from './SuperAdminDashboard';
// import ChefProjetDashboard  from './ChefProjetDashboard';

// ── Formatters ────────────────────────────────────────────────────────────────
const fmtFCFA = (n) => {
  if (!n && n !== 0) return '—';
  const num = parseFloat(n);
  if (num >= 1_000_000_000) return `${(num / 1_000_000_000).toFixed(1)} Mrd`;
  if (num >= 1_000_000)     return `${(num / 1_000_000).toFixed(1)} M`;
  if (num >= 1_000)         return `${Math.round(num / 1_000)} K`;
  return `${num.toLocaleString('fr-FR')}`;
};

const fmtDate = (d) => {
  if (!d) return '—';
  return new Date(d + 'T00:00:00').toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' });
};

const STATUS_CFG = {
  planifie: { label: 'Planifié',  color: '#6366F1', bg: 'rgba(99,102,241,0.12)'  },
  en_cours: { label: 'En cours',  color: '#F59E0B', bg: 'rgba(245,158,11,0.12)'  },
  suspendu: { label: 'Suspendu',  color: '#EF4444', bg: 'rgba(239,68,68,0.12)'   },
  termine:  { label: 'Terminé',   color: '#10B981', bg: 'rgba(16,185,129,0.12)'  },
};

const WEATHER_ICONS = {
  ensoleille: '☀️', nuageux: '☁️', pluvieux: '🌧️', venteux: '💨', orageux: '⛈️'
};

const PURCHASE_STATUT_CFG = {
  livre:      { label: 'Livré',    color: '#10B981' },
  commande:   { label: 'Commandé', color: '#3B82F6' },
  en_attente: { label: 'Attente',  color: '#F59E0B' },
  annule:     { label: 'Annulé',   color: '#EF4444' },
};

// ── Shared mini UI ─────────────────────────────────────────────────────────────
function KPI({ label, value, sub, color = '#F59E0B', alert, icon }) {
  return (
    <div style={{
      background: '#111827',
      border: `1px solid ${alert ? 'rgba(239,68,68,0.4)' : 'rgba(255,255,255,0.07)'}`,
      borderRadius: 12, padding: '20px 22px', position: 'relative',
    }}>
      {alert && <span style={{ position: 'absolute', top: 10, right: 10, width: 8, height: 8, borderRadius: '50%', background: '#EF4444', boxShadow: '0 0 6px #EF4444' }} />}
      {icon && <div style={{ fontSize: 22, marginBottom: 8 }}>{icon}</div>}
      <div style={{ fontSize: 26, fontWeight: 800, color: alert ? '#EF4444' : color, fontFamily: 'Bebas Neue', letterSpacing: 1, marginBottom: 4 }}>{value ?? '—'}</div>
      <div style={{ fontSize: 11, color: '#6B7280', textTransform: 'uppercase', letterSpacing: '0.6px' }}>{label}</div>
      {sub && <div style={{ fontSize: 11, color: alert ? '#EF4444' : '#9CA3AF', marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

function Alert({ text, type = 'warning' }) {
  const cfg = {
    warning: { bg: 'rgba(245,158,11,0.1)',  border: 'rgba(245,158,11,0.3)',  color: '#F59E0B',  icon: '⚠️' },
    danger:  { bg: 'rgba(239,68,68,0.08)', border: 'rgba(239,68,68,0.25)',  color: '#FCA5A5', icon: '🔴' },
    info:    { bg: 'rgba(59,130,246,0.08)', border: 'rgba(59,130,246,0.2)',  color: '#93C5FD', icon: 'ℹ️' },
    success: { bg: 'rgba(16,185,129,0.08)', border: 'rgba(16,185,129,0.2)', color: '#34D399', icon: '✅' },
  }[type];
  return (
    <div style={{ background: cfg.bg, border: `1px solid ${cfg.border}`, borderRadius: 10, padding: '12px 16px', marginBottom: 20, fontSize: 13, color: cfg.color, display: 'flex', alignItems: 'center', gap: 10 }}>
      <span style={{ fontSize: 15 }}>{cfg.icon}</span> {text}
    </div>
  );
}

function SectionTitle({ children, action, actionTo, actionFn }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
      <h2 style={{ fontFamily: 'Bebas Neue', fontSize: 18, color: '#fff', letterSpacing: 1, margin: 0 }}>{children}</h2>
      {action && (actionTo
        ? <Link to={actionTo} style={{ fontSize: 12, color: '#F59E0B', textDecoration: 'none', fontWeight: 600 }}>{action} →</Link>
        : <button onClick={actionFn} style={{ background: 'none', border: 'none', fontSize: 12, color: '#F59E0B', cursor: 'pointer', fontWeight: 600, padding: 0 }}>{action} →</button>
      )}
    </div>
  );
}

function Card({ children, style = {} }) {
  return (
    <div style={{ background: '#111827', border: '1px solid rgba(255,255,255,0.07)', borderRadius: 14, padding: 22, ...style }}>
      {children}
    </div>
  );
}

function ProgressBar({ pct, color, height = 7 }) {
  const c = color || (pct > 85 ? '#EF4444' : pct > 60 ? '#F59E0B' : '#3B82F6');
  return (
    <div style={{ height, background: 'rgba(255,255,255,0.07)', borderRadius: height / 2, overflow: 'hidden' }}>
      <div style={{ height: '100%', width: `${Math.min(100, pct || 0)}%`, background: c, borderRadius: height / 2, transition: 'width 0.7s ease' }} />
    </div>
  );
}

function StatusBadge({ status }) {
  const cfg = STATUS_CFG[status] || STATUS_CFG.planifie;
  return <span style={{ padding: '2px 10px', borderRadius: 100, fontSize: 11, fontWeight: 600, color: cfg.color, background: cfg.bg }}>{cfg.label}</span>;
}

function ProjectRow({ p }) {
  return (
    <Link to={`/projects/${p.id}`} style={{ textDecoration: 'none' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 14px', borderRadius: 10, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', marginBottom: 8, cursor: 'pointer', transition: 'background 0.15s' }}
        onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.06)'}
        onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
      >
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: '#fff', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</div>
          {p.location && <div style={{ fontSize: 11, color: '#6B7280' }}>📍 {p.location}</div>}
        </div>
        <StatusBadge status={p.status} />
        {p.budget_consumed_pct != null && (
          <span style={{ fontSize: 12, color: p.budget_consumed_pct > 85 ? '#EF4444' : '#9CA3AF', fontWeight: 600, minWidth: 36, textAlign: 'right' }}>{p.budget_consumed_pct}%</span>
        )}
      </div>
    </Link>
  );
}

function EmptyState({ icon, text }) {
  return (
    <div style={{ textAlign: 'center', padding: '32px 0', color: '#4B5563' }}>
      <div style={{ fontSize: 32, marginBottom: 8 }}>{icon}</div>
      <div style={{ fontSize: 13 }}>{text}</div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// EXISTING ROLE DASHBOARDS (unchanged from your codebase)
// ══════════════════════════════════════════════════════════════════════════════

function DashboardMaitreOeuvre({ projects }) {
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Projets suivis"  value={projects.length}                                     icon="📐" color="#22D3EE" />
        <KPI label="En cours"        value={projects.filter(p => p.status === 'en_cours').length} icon="⚡" color="#F59E0B" />
        <KPI label="Terminés"        value={projects.filter(p => p.status === 'termine').length}  icon="✅" color="#10B981" />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle>Avancement technique</SectionTitle>
          {projects.length === 0 ? <EmptyState icon="📐" text="Aucun projet assigné." /> : projects.map(p => (
            <div key={p.id} style={{ marginBottom: 16 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, color: '#D1D5DB', marginBottom: 5 }}>
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 200 }}>{p.name}</span>
                <span style={{ color: '#9CA3AF' }}>{p.progress_pct || 0}%</span>
              </div>
              <ProgressBar pct={p.progress_pct || 0} color="#22D3EE" />
            </div>
          ))}
        </Card>
        <Card>
          <SectionTitle action="Accéder" actionTo="/documents">Documents techniques</SectionTitle>
          <Alert text="Le module Documents sera disponible en Phase 2." type="info" />
          {projects.slice(0, 4).map(p => (
            <Link key={p.id} to={`/projects/${p.id}`} style={{ textDecoration: 'none' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <span style={{ fontSize: 20 }}>📋</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{p.name}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{p.project_type_display}</div>
                </div>
                <StatusBadge status={p.status} />
              </div>
            </Link>
          ))}
        </Card>
      </div>
    </>
  );
}

function DashboardConducteur({ projects, stats }) {
  const reports = stats?.recent_reports || [];
  const incidents = reports.reduce((a, r) => a + (r.incidents_count || 0), 0);
  return (
    <>
      <div style={{ background: '#111827', border: '1px solid rgba(255,255,255,0.07)', borderRadius: 14, padding: '16px 22px', marginBottom: 20, display: 'flex', gap: 32, flexWrap: 'wrap' }}>
        {[
          { value: projects.filter(p => p.status === 'en_cours').length, label: 'Projets actifs',     color: '#F59E0B' },
          { value: reports[0]?.workers_count || 0,                       label: 'Ouvriers (dernier)', color: '#10B981' },
          { value: incidents,                                             label: 'Incidents (5j)',     color: '#EF4444' },
          { value: reports.length,                                        label: 'Rapports (5j)',      color: '#06B6D4' },
        ].map((s, i) => (
          <div key={i} style={{ textAlign: 'center' }}>
            <div style={{ fontSize: 28, fontWeight: 800, color: s.color, fontFamily: 'Bebas Neue' }}>{s.value}</div>
            <div style={{ fontSize: 11, color: '#6B7280', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle action="+ Nouveau" actionTo="/projects">Journal de chantier (5 derniers jours)</SectionTitle>
          {reports.length === 0 ? <EmptyState icon="📓" text="Aucun rapport récent." /> : reports.map(r => (
            <Link key={r.id} to={`/projects/${r.project_id}/reports/${r.id}`} style={{ textDecoration: 'none' }}>
              <div style={{ display: 'flex', gap: 14, padding: '12px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', cursor: 'pointer' }}>
                <div style={{ textAlign: 'center', flexShrink: 0, width: 36 }}>
                  <div style={{ fontSize: 18, fontWeight: 800, color: '#F59E0B', fontFamily: 'Bebas Neue' }}>{new Date(r.report_date + 'T00:00:00').getDate()}</div>
                  <div style={{ fontSize: 9, color: '#6B7280', textTransform: 'uppercase' }}>{new Date(r.report_date + 'T00:00:00').toLocaleDateString('fr-FR', { month: 'short' })}</div>
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff', marginBottom: 3 }}>{r.project_name} {WEATHER_ICONS[r.weather] || ''}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{r.workers_count} ouvriers · avancement {r.progress_pct ?? '—'}%</div>
                  <div style={{ display: 'flex', gap: 6, marginTop: 5 }}>
                    {r.is_validated && <span style={{ padding: '2px 8px', borderRadius: 100, fontSize: 10, fontWeight: 600, background: 'rgba(16,185,129,0.12)', color: '#34D399' }}>✓ Validé</span>}
                    {r.incidents_count > 0 && <span style={{ padding: '2px 8px', borderRadius: 100, fontSize: 10, fontWeight: 600, background: 'rgba(239,68,68,0.12)', color: '#FCA5A5' }}>⚠ {r.incidents_count} incident</span>}
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </Card>
        <Card>
          <SectionTitle>Mes projets</SectionTitle>
          {projects.length === 0 ? <EmptyState icon="🏗️" text="Aucun projet assigné." /> : projects.map(p => <ProjectRow key={p.id} p={p} />)}
          <div style={{ marginTop: 16 }}>
            <Link to="/projects" style={{ display: 'block', textAlign: 'center', padding: '9px 0', borderRadius: 8, background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.25)', color: '#F59E0B', fontSize: 13, fontWeight: 600, textDecoration: 'none' }}>
              + Nouvelle entrée journal
            </Link>
          </div>
        </Card>
      </div>
    </>
  );
}

function DashboardChefChantier({ projects, stats }) {
  const reports = stats?.recent_reports || [];
  const today   = reports[0];
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, marginBottom: 24 }}>
        <KPI label="Projets assignés"   value={projects.length}           icon="🏗️" color="#FB923C" />
        <KPI label="Ouvriers (dernier)" value={today?.workers_count || 0} icon="👷" color="#F59E0B" />
        <KPI label="Incidents (5j)"     value={reports.reduce((a, r) => a + (r.incidents_count || 0), 0)} icon="⚠️" color="#EF4444" alert={reports.some(r => r.incidents_count > 0)} />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle>Mes chantiers</SectionTitle>
          {projects.length === 0 ? <EmptyState icon="🏗️" text="Aucun projet assigné." /> : projects.map(p => (
            <Link key={p.id} to={`/projects/${p.id}`} style={{ textDecoration: 'none' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{p.name}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{p.location || ''}</div>
                  <div style={{ marginTop: 5 }}><ProgressBar pct={p.progress_pct || 0} color="#FB923C" height={4} /></div>
                </div>
                <StatusBadge status={p.status} />
              </div>
            </Link>
          ))}
          <div style={{ marginTop: 14 }}>
            <Link to="/projects" style={{ display: 'block', textAlign: 'center', padding: '9px 0', borderRadius: 8, background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.25)', color: '#F59E0B', fontSize: 13, fontWeight: 600, textDecoration: 'none' }}>
              + Nouvelle entrée journal
            </Link>
          </div>
        </Card>
        <Card>
          <SectionTitle>Rapports récents</SectionTitle>
          {reports.length === 0 ? <EmptyState icon="📓" text="Aucun rapport encore." /> : reports.map(r => (
            <Link key={r.id} to={`/projects/${r.project_id}/reports/${r.id}`} style={{ textDecoration: 'none' }}>
              <div style={{ display: 'flex', gap: 10, padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <span style={{ fontSize: 22 }}>{WEATHER_ICONS[r.weather] || '📅'}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{new Date(r.report_date + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: '2-digit', month: 'short' })}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{r.workers_count} ouvriers · {r.project_name}</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  {r.is_validated ? <span style={{ fontSize: 11, color: '#10B981' }}>✓ Validé</span> : <span style={{ fontSize: 11, color: '#F59E0B' }}>En attente</span>}
                </div>
              </div>
            </Link>
          ))}
          <div style={{ marginTop: 14 }}>
            <Link to="/projects" style={{ display: 'block', textAlign: 'center', padding: '9px 0', borderRadius: 8, background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.25)', color: '#FCA5A5', fontSize: 13, fontWeight: 600, textDecoration: 'none' }}>
              ⚠️ Signaler un incident
            </Link>
          </div>
        </Card>
      </div>
    </>
  );
}

function DashboardQHSE({ projects, stats }) {
  const reports  = stats?.recent_reports || [];
  const totalInc = reports.reduce((a, r) => a + (r.incidents_count || 0), 0);
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Projets suivis"   value={projects.length}      icon="🛡️" color="#F87171" />
        <KPI label="Incidents (5j)"   value={totalInc}             icon="⚠️" color="#EF4444" alert={totalInc > 0} />
        <KPI label="Rapports validés" value={reports.filter(r => r.is_validated).length} icon="✅" color="#10B981" />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle>Incidents signalés (5 derniers jours)</SectionTitle>
          {totalInc === 0 ? <EmptyState icon="✅" text="Aucun incident sur les 5 derniers jours." /> : reports.filter(r => r.incidents_count > 0).map(r => (
            <Link key={r.id} to={`/projects/${r.project_id}/reports/${r.id}`} style={{ textDecoration: 'none' }}>
              <div style={{ display: 'flex', gap: 10, padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ width: 36, height: 36, borderRadius: '50%', background: 'rgba(239,68,68,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, flexShrink: 0 }}>⚠️</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#FCA5A5' }}>{r.incidents_count} incident(s)</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{r.project_name} · {fmtDate(r.report_date)}</div>
                </div>
              </div>
            </Link>
          ))}
        </Card>
        <Card>
          <SectionTitle>Suivi par projet</SectionTitle>
          {projects.map(p => (
            <div key={p.id} style={{ marginBottom: 16 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, color: '#D1D5DB', marginBottom: 5 }}>
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 180 }}>{p.name}</span>
                <span style={{ color: '#9CA3AF' }}>{p.progress_pct || 0}%</span>
              </div>
              <ProgressBar pct={p.progress_pct || 0} color="#F87171" />
            </div>
          ))}
          {projects.length === 0 && <EmptyState icon="🛡️" text="Aucun projet assigné." />}
        </Card>
      </div>
    </>
  );
}

function DashboardFinancier({ projects, stats }) {
  const purchases  = stats?.recent_purchases || [];
  const totalBudget = projects.reduce((a, p) => a + (parseFloat(p.budget) || 0), 0);
  const totalExp    = projects.reduce((a, p) => a + (parseFloat(p.actual_expenses) || 0), 0);
  const globalPct   = totalBudget > 0 ? Math.round((totalExp / totalBudget) * 100) : 0;
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Budget total"     value={`${fmtFCFA(totalBudget)} FCFA`} icon="💼" color="#10B981" />
        <KPI label="Dépenses réelles" value={`${fmtFCFA(totalExp)} FCFA`}    icon="💸" color="#EF4444" alert={globalPct > 85} sub={`${globalPct}% consommé`} />
        <KPI label="Achats récents"   value={purchases.length}                icon="🛒" color="#F59E0B" />
        <KPI label="Projets suivis"   value={projects.length}                 icon="🏗️" color="#6366F1" />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle>Registre des achats récents</SectionTitle>
          {purchases.length === 0 ? <EmptyState icon="🛒" text="Aucun achat enregistré." /> : (
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr>{['Date', 'Désignation', 'Fournisseur', 'Total FCFA', 'Statut'].map(h => (
                  <th key={h} style={{ textAlign: 'left', padding: '5px 6px', fontSize: 10, color: '#6B7280', fontWeight: 600, textTransform: 'uppercase', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>{h}</th>
                ))}</tr>
              </thead>
              <tbody>
                {purchases.map((p, i) => {
                  const sc = PURCHASE_STATUT_CFG[p.statut] || { label: p.statut, color: '#9CA3AF' };
                  return (
                    <tr key={i} style={{ borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                      <td style={{ padding: '9px 6px', color: '#6B7280' }}>{fmtDate(p.date_commande)}</td>
                      <td style={{ padding: '9px 6px', color: '#fff', fontWeight: 600, maxWidth: 120, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.designation}</td>
                      <td style={{ padding: '9px 6px', color: '#9CA3AF' }}>{p.fournisseur || '—'}</td>
                      <td style={{ padding: '9px 6px', color: '#D1D5DB' }}>{fmtFCFA(p.total)}</td>
                      <td style={{ padding: '9px 6px' }}><span style={{ padding: '2px 8px', borderRadius: 100, fontSize: 10, fontWeight: 600, color: sc.color, background: `${sc.color}1a` }}>{sc.label}</span></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </Card>
        <Card>
          <SectionTitle>Budget vs Dépenses par projet</SectionTitle>
          {projects.length === 0 ? <EmptyState icon="💰" text="Aucun projet." /> : projects.map(p => {
            const budget = parseFloat(p.budget) || 0;
            const exp    = parseFloat(p.actual_expenses) || 0;
            const pct    = budget > 0 ? Math.min(100, Math.round((exp / budget) * 100)) : 0;
            return (
              <div key={p.id} style={{ marginBottom: 18 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 5 }}>
                  <span style={{ fontSize: 13, color: '#D1D5DB', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 180 }}>{p.name}</span>
                  <span style={{ fontSize: 12, color: pct > 85 ? '#EF4444' : '#9CA3AF', fontWeight: 600, marginLeft: 8 }}>{pct}%</span>
                </div>
                <ProgressBar pct={pct} />
                <div style={{ fontSize: 11, color: '#4B5563', marginTop: 3 }}>{fmtFCFA(exp)} / {fmtFCFA(budget)} FCFA</div>
              </div>
            );
          })}
        </Card>
      </div>
    </>
  );
}

