const PAGE_TITLES = {
  super_admin:   "Administration — Vue d'ensemble",
  chef_projet:   "Vue d'ensemble — Mes projets",
  maitre_oeuvre: 'Documents & Conformité technique',
  conducteur:    'Journal de Chantier',
  chef_chantier: 'Mon chantier du jour',
  qhse:          'Contrôle Qualité & Sécurité (QHSE)',
  financier:     'Budget & Achats',
  magasinier:    'Gestion Stocks & Livraisons',
  sous_traitant: 'Mes tâches & Mon équipe',
  client:        "Suivi — Mes projets",
};

const ACTION_BTNS = {
  chef_projet:   { label: 'Générer rapport IA', to: '/reports',  primary: true, color: '#6366F1' },
  conducteur:    { label: '+ Nouvelle entrée',  to: '/projects', primary: true, color: '#F59E0B' },
  chef_chantier: { label: '+ Pointer heures',   to: '/projects', primary: true, color: '#F59E0B' },
  qhse:          { label: 'Rapport QHSE',       to: '/qhse',     primary: true, color: '#F87171' },
  financier:     { label: 'Exporter rapport',   to: '/budget',   primary: true, color: '#F59E0B' },
  sous_traitant: { label: 'Upload photos',      to: '/projects', primary: true, color: '#C084FC' },
  super_admin:   { label: '+ Inviter membre',   to: '/team',     primary: false, color: '#9CA3AF' },
};

// ══════════════════════════════════════════════════════════════════════════════
// MAIN DASHBOARD ROUTER
// ══════════════════════════════════════════════════════════════════════════════

export default function DashboardPage() {
  const { user }                      = useAuth();
  const { role, roleColor, roleIcon } = usePermissions();
  const [projects, setProjects]       = useState([]);
  const [stats, setStats]             = useState(null);
  const [team, setTeam]               = useState([]);
  const [loading, setLoading]         = useState(true);

  useEffect(() => {
    const calls = [
      projectsAPI.list().catch(() => ({ data: [] })),
      projectsAPI.getDashboardStats().catch(() => ({ data: null })),
    ];
    if (role === 'super_admin') calls.push(teamAPI.list().catch(() => ({ data: [] })));

    Promise.all(calls).then(([pRes, sRes, tRes]) => {
      setProjects(pRes.data || []);
      setStats(sRes.data || null);
      if (tRes) setTeam(tRes.data || []);
    }).finally(() => setLoading(false));
  }, [role]);

  // NOTE: Once you place SuperAdminDashboard.jsx and ChefProjetDashboard.jsx in the
  // pages/dashboard/ folder, uncomment these early-returns to use the specialized dashboards:
  //
  // if (role === 'super_admin' && !loading) return <SuperAdminDashboard />;
  // if (role === 'chef_projet' && !loading) return <ChefProjetDashboard />;

  const btn = ACTION_BTNS[role];

  return (
    <AppLayout>
      <div style={{ padding: '32px 36px', background: '#0A0F1E', minHeight: '100vh' }} className="animate-fade-in">

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 28 }}>
          <div>
            <p style={{ color: '#6B7280', fontSize: 12, margin: '0 0 4px', fontFamily: 'Barlow Condensed', letterSpacing: 0.5, textTransform: 'uppercase' }}>
              {new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
            <h1 style={{ fontFamily: 'Bebas Neue', fontSize: 26, color: '#fff', letterSpacing: 1, margin: '0 0 8px' }}>
              {PAGE_TITLES[role] || 'Tableau de bord'}
            </h1>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <RoleBadge role={role} size="sm" />
              <span style={{ fontSize: 12, color: '#6B7280' }}>{user?.full_name} · {user?.company_name}</span>
            </div>
          </div>

          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexShrink: 0 }}>
            <Link to="/projects" style={{ padding: '9px 18px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'transparent', color: '#9CA3AF', fontSize: 13, fontWeight: 600, textDecoration: 'none', fontFamily: 'Barlow Condensed' }}>
              Mes projets
            </Link>
            {btn && (
              <Link to={btn.to} style={{ padding: '9px 20px', borderRadius: 8, background: btn.primary ? btn.color : 'transparent', border: `1px solid ${btn.color}`, color: btn.primary ? '#0D0D1A' : btn.color, fontSize: 13, fontWeight: 700, textDecoration: 'none', fontFamily: 'Barlow Condensed' }}>
                {btn.label}
              </Link>
            )}
          </div>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '80px 0' }}>
            <div style={{ width: 36, height: 36, border: '3px solid #F59E0B', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 14px' }} />
            <p style={{ color: '#6B7280', fontSize: 14 }}>Chargement de votre tableau de bord...</p>
          </div>
        ) : (
          <>
            {role === 'maitre_oeuvre' && <DashboardMaitreOeuvre projects={projects} stats={stats} />}
            {role === 'conducteur'    && <DashboardConducteur   projects={projects} stats={stats} />}
            {role === 'chef_chantier' && <DashboardChefChantier projects={projects} stats={stats} />}
            {role === 'qhse'          && <DashboardQHSE         projects={projects} stats={stats} />}
            {role === 'financier'     && <DashboardFinancier    projects={projects} stats={stats} />}
            {role === 'magasinier'    && <DashboardMagasinier   projects={projects} stats={stats} />}
            {role === 'sous_traitant' && <DashboardSousTraitant projects={projects} stats={stats} />}
            {role === 'client'        && <DashboardClient       projects={projects} stats={stats} />}

            {/* For super_admin and chef_projet, show the full version inline
                until the specialized files are placed. */}
            {role === 'super_admin' && (
              <div style={{ background: 'rgba(245,158,11,0.06)', border: '1px solid rgba(245,158,11,0.15)', borderRadius: 12, padding: 20, textAlign: 'center', color: '#F59E0B', fontSize: 14 }}>
                ✅ Placez <code style={{ background: 'rgba(0,0,0,0.3)', padding: '2px 6px', borderRadius: 4, fontSize: 12 }}>SuperAdminDashboard.jsx</code> dans ce dossier et décommentez l'import en haut de ce fichier pour activer le tableau de bord complet.
              </div>
            )}
            {role === 'chef_projet' && (
              <div style={{ background: 'rgba(99,102,241,0.06)', border: '1px solid rgba(99,102,241,0.15)', borderRadius: 12, padding: 20, textAlign: 'center', color: '#818CF8', fontSize: 14 }}>
                ✅ Placez <code style={{ background: 'rgba(0,0,0,0.3)', padding: '2px 6px', borderRadius: 4, fontSize: 12 }}>ChefProjetDashboard.jsx</code> dans ce dossier et décommentez l'import en haut de ce fichier pour activer le tableau de bord complet.
              </div>
            )}
          </>
        )}

      </div>
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </AppLayout>
  );
}
